    lan_cuoi = {}  # ký tự -> chỉ số gần nhất
    trai = 0
    dai_nhat = 0

    for phai, c in enumerate(s):
        # Chỉ kéo mép trái khi ký tự trùng nằm TRONG cửa sổ hiện tại.
        if c in lan_cuoi and lan_cuoi[c] >= trai:
